import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getLeaderboardHandler } from "../handlers/getLeaderboardHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof getLeaderboardHandler>>;

export function useGetLeaderboard(
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getLeaderboard", bookmark],
    queryFn: () => getLeaderboardHandler(bookmark),
    ...options,
  });
}
